// Workspace presentation inspired by the supplied Omni CRM prototype.
// Business writes still go through the existing authenticated service APIs.
const icons={home:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2 M7 14h2 M12 14h2 M7 18h2',chat:'M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8z',sales:'M4 4v5h5 M4 17h5v-5 M9 7h11 M9 15h11 M9 21h7',quote:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h4',bot:'M12 3v3 M8 3h4 M5 6h14v13H5z M2 10v5 M22 10v5 M9 10v2 M15 10v2 M9 16h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',search:'M21 21l-5-5 M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15',channel:'M4 8a11 11 0 0 1 16 0 M7 11a7 7 0 0 1 10 0 M10 14a3 3 0 0 1 4 0 M12 18h.01',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 17h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',logout:'M9 3H4v18h5 M15 8l5 4-5 4 M9 12h11',check:'M5 12l4 4L19 6',plus:'M12 5v14 M5 12h14'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.quote}"/></svg>`;
const initials=name=>String(name||'?').replace(/\([^)]*\)/g,'').trim().split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase();
const avatar=(name,tone='')=>`<span class="avatar ${tone}">${esc(initials(name))}</span>`;
const empty=(title,detail='')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(detail)}</div>`;
const moneyShort=n=>n>=1e9?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(n/1e9)+' tỷ':n>=1e6?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(n/1e6)+' tr':vnd(n);
const vietnamDay=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const dueText=d=>d?new Date(d).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'Chưa đặt hạn';
const taskCreatedText=d=>d&&Number.isFinite(Date.parse(d))?new Date(d).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'})+' (giờ Việt Nam)':'Chưa ghi nhận';
const taskHistoryText=text=>String(text||'').replace(/(Đổi trạng thái: )(OPEN|IN_PROGRESS|BLOCKED|COMPLETED)( → )(OPEN|IN_PROGRESS|BLOCKED|COMPLETED)(?=$|\.)/g,(_,prefix,from,arrow,to)=>prefix+workStateLabel(from)+arrow+workStateLabel(to)).replace(/(Tự cập nhật theo công việc con: )(OPEN|IN_PROGRESS|BLOCKED|COMPLETED)(?=$|\.)/g,(_,prefix,state)=>prefix+workStateLabel(state));
const late=t=>t.status!=='COMPLETED'&&t.due_at&&Date.parse(t.due_at)<Date.now();
const channelName=v=>String(v).includes('cá nhân')?'Zalo cá nhân':'Zalo OA';
const channelId=v=>String(v).includes('cá nhân')?'personal':'oa';
const pageHeading=(title,description,buttons='')=>`<div class="eyebrow">SMART OMNI CRM / ${esc(me?.company?.name||'iViTech')}</div><div class="page-heading"><div><h2>${esc(title)}</h2><p class="lead">${esc(description)}</p></div><div class="actions">${buttons}</div></div>`;
const stageColors=['#8cb0c3','#a395bc','#d2b27f','#8faf98','#cfaa80','#63977c','#bf969b'];
const navItems=[['home','Tổng quan','home',0],['customers','Danh bạ khách hàng','people',0],['tasks','Kế hoạch tiếp xúc','calendar',0],['inbox','Hộp thư Zalo','chat',1],['pipeline','Cơ hội bán hàng','sales',1],['quotes','Báo giá & phê duyệt','quote',1],['knowledge','Nội dung & bot FAQ','bot',2],['channels','Kênh kết nối','channel',2],['templates','Mẫu & nhận diện','quote',3],['settings','Cấu hình công ty','settings',3],['users','Người dùng','people',3],['guide','Hướng dẫn kiểm thử','help',3]];
const roleTitle={sales:'Nhân viên sales',leader:'Trưởng nhóm',director:'Giám đốc',admin:'Quản trị'};
const roleNav=()=>me.role==='admin'&&me.admin_level==='subadmin'?['home','templates','users','channels','guide']:me.role==='admin'?['home','templates','settings','users','channels','guide']:me.role==='director'?['home','quotes','knowledge','channels','guide']:navItems.filter(n=>n[0]!=='users').map(n=>n[0]);
async function logoutAccount(){await api('/logout',{body:{}});me=null;err='';document.querySelectorAll('dialog').forEach(d=>d.remove());go('#/home');render();}
async function quickSearch(){
 const [customers,opportunities,quotes,tasks]=await Promise.all([api('/customers'),api('/opportunities'),api('/quotes'),api('/tasks')]);
 const records=[...customers.map(x=>({title:x.name,meta:'Khách hàng · '+(x.phone||x.interest||''),href:'#/customer/'+x.id})),...opportunities.map(x=>({title:x.title,meta:'Cơ hội · '+x.customer_name,href:'#/opportunity/'+x.id})),...quotes.map(x=>({title:x.code+' · v'+x.version,meta:'Báo giá · '+x.customer_name,href:'#/quote/'+x.id})),...tasks.map(x=>({title:x.title,meta:'Kế hoạch · '+(x.customer_name||''),href:'#/tasks/'+x.id}))];
 const d=$(`<dialog><div class="section-heading"><h3>Tìm trong phạm vi của bạn</h3><button id="dismiss" aria-label="Đóng">×</button></div><input id="find-record" placeholder="Tên khách, cơ hội, báo giá, công việc…" aria-label="Từ khóa tìm kiếm"><div class="search-results" style="max-height:55vh;overflow:auto"></div></dialog>`);document.body.append(d);d.showModal();
 const fill=()=>{const s=d.querySelector('input').value.toLocaleLowerCase('vi');const list=records.filter(x=>(x.title+' '+x.meta).toLocaleLowerCase('vi').includes(s)).slice(0,20);d.querySelector('.search-results').innerHTML=list.map(x=>`<a href="${x.href}"><strong>${esc(x.title)}</strong><small>${esc(x.meta)}</small></a>`).join('')||empty('Không có kết quả phù hợp');d.querySelectorAll('a').forEach(a=>a.onclick=()=>d.close());};fill();d.querySelector('input').oninput=fill;d.querySelector('#dismiss').onclick=()=>d.close();d.onclose=()=>d.remove();d.querySelector('input').focus();
}
const previousWorkspaceRender=render;removeEventListener('hashchange',previousWorkspaceRender);let workspaceSequence=0;
render=async function(){
 const seq=++workspaceSequence,root=document.getElementById('root');if(!me){root.replaceChildren(loginView());return;}
 const [,name='home',id]=(location.hash||'#/home').split('/');
 const section=({customer:'customers',conversation:'inbox',opportunity:'pipeline',quote:'quotes',print:'quotes',article:'knowledge',import:'customers',audit:'users'})[name]||name;
 const visible=roleNav(),item=navItems.find(n=>n[0]===section),title=item?.[1]||'Không gian làm việc';
 const shell=$(`<div class="workspace"><nav class="workspace-nav" aria-label="Điều hướng chính"><a class="workspace-brand" href="#/home"><span class="brand-mark">iV</span><span class="wordmark">omni<small>CRM</small></span></a><div class="workspace-name"><strong style="font-size:13px">${esc(me.company?.name||'iViTech')}</strong><div class="who">Bản thử nội bộ trên máy</div></div><div class="nav-links">${['KHÔNG GIAN LÀM VIỆC','KẾT NỐI & BÁN HÀNG','BOT & KÊNH KẾT NỐI','QUẢN TRỊ'].map((group,i)=>{const links=navItems.filter(n=>n[3]===i&&visible.includes(n[0]));return links.length?`<div class="nav-group-title">${group}</div>${links.map(([key,label,glyph])=>`<a href="#/${key}" class="nav-link ${section===key?'on':''}">${icon(glyph)}<span>${label}</span></a>`).join('')}`:'';}).join('')}</div><div class="nav-bottom"><div class="identity">${avatar(me.name)}<div><strong style="font-size:12px">${esc(me.name)}</strong><small>${me.admin_level==='subadmin'?'Subadmin':roleTitle[me.role]}</small></div></div><button id="out">${icon('logout')} Đăng xuất</button><p class="small">Dữ liệu lưu trên máy · v0.5</p></div></nav><div class="workspace-main"><header class="workspace-top"><div class="breadcrumbs"><span>Không gian làm việc</span><span>›</span><strong>${esc(title)}</strong></div><div class="top-tools"><button id="global-search" aria-label="Tìm kiếm nhanh">${icon('search')} <span class="search-label">Tìm kiếm…</span><kbd>Ctrl K</kbd></button><span class="local-state">Bản thử nội bộ</span><button class="account-switch" id="switch-account" title="Đổi tài khoản" aria-label="Đổi tài khoản">${avatar(me.name)}<span class="account-label">Đổi tài khoản</span></button></div></header><main id="main"><div class="loading">Đang tải…</div></main><footer class="workspace-footer"><span>Dữ liệu lưu tại localhost · Xem trạng thái từng kênh trong Kênh kết nối</span><span>Smart Omni CRM / ${esc(me.company?.name||'iViTech')}</span></footer></div></div>`);
 root.replaceChildren(shell);action(shell,'#out,#switch-account',logoutAccount);action(shell,'#global-search',quickSearch);
 try{const view=await (views[name]||views.home)(id);if(seq!==workspaceSequence)return;shell.querySelector('#main').replaceChildren(view);if(err){view.prepend($(`<div class="notice">${esc(err)}</div>`));err='';}}
 catch(e){if(seq!==workspaceSequence)return;shell.querySelector('#main').replaceChildren($(`<div class="card"><h2>Không mở được</h2><p class="err">${esc(e.message)}</p><a href="#/home">Về tổng quan</a></div>`));}
};
addEventListener('hashchange',()=>{document.querySelector('.toast')?.remove();render();});
addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&me){e.preventDefault();quickSearch().catch(e=>toast(e.message));}});

views.home=async()=>{
 const [d,opps,tasks,conversations,pending]=await Promise.all([api('/home'),api('/opportunities'),api('/tasks'),api('/conversations'),api('/quotes/pending')]);const open=opps.filter(x=>!['Thắng','Thua'].includes(x.stage));
 const upcoming=tasks.filter(t=>t.status!=='COMPLETED').sort((a,b)=>(a.due_at?Date.parse(a.due_at):Infinity)-(b.due_at?Date.parse(b.due_at):Infinity)).slice(0,4);
 const el=$(`<div>${pageHeading('Tổng quan công việc','Chào '+me.name+'. Những khách hàng và việc cần bạn tiếp tục hôm nay.',writable()?`<button class="major" id="create">${icon('plus')} Tạo mới</button>`:'')}<div class="section-heading"><span class="small">${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'})}</span><span class="local-state">${me.admin_level==='subadmin'?'Subadmin':roleTitle[me.role]} · đúng phạm vi được giao</span></div><div class="metrics">${(writable()?[[d.customers,'Khách hàng trong phạm vi','people','Tổ chức và cá nhân'],[moneyShort(d.open_value),'Giá trị cơ hội đang mở','sales',open.length+' cơ hội'],[d.overdue_tasks,'Việc đã quá hạn','calendar','Cần ưu tiên liên hệ'],[pending.length,'Báo giá chờ bạn duyệt','quote','Theo cấp duyệt của bạn']]:[[pending.length,'Báo giá chờ bạn duyệt','quote','Đúng cấp duyệt'],[d.knowledge_pending||0,'Nội dung bot chờ duyệt','bot','Chỉ bản được duyệt mới sử dụng'],['02','Loại kênh Zalo thử','channel','OA và cá nhân công ty'],[roleTitle[me.role],'Vai trò đang dùng','people','Đổi tài khoản trên thanh đầu trang']]).map(([value,label,glyph,foot])=>`<div class="metric"><div class="metric-title">${label}${icon(glyph)}</div><strong class="metric-value">${esc(value)}</strong><span class="metric-foot">${foot}</span></div>`).join('')}</div><div class="dashboard-grid"><section class="card"><div class="section-heading"><div><h3>${writable()?'Tình hình cơ hội bán hàng':'Việc cần phê duyệt'}</h3><p>${writable()?'Từ nhu cầu ban đầu đến hợp đồng đã ký.':'Mở đúng bản ghi để kiểm tra trước khi duyệt.'}</p></div><a href="#/${writable()?'pipeline':'quotes'}">${writable()?'Xem cơ hội':'Xem báo giá'} →</a></div>${writable()?`<span class="metric-value">${moneyShort(d.open_value)} <small>VNĐ</small></span><div class="stage-summary">${STAGES.filter(s=>!['Thắng','Thua'].includes(s)).map((s,i)=>{const deals=open.filter(o=>o.stage===s),value=deals.reduce((a,o)=>a+o.est_value,0);return `<a class="stage-meter" href="#/pipeline"><div class="balance"><span>${esc(s)}</span><span>${moneyShort(value)}</span></div><div class="meter"><span style="width:${d.open_value?Math.round(value*100/d.open_value):0}%;background:${stageColors[i%stageColors.length]}"></span></div><small>${deals.length} cơ hội</small></a>`;}).join('')}</div><p class="small">${d.won} thắng · ${d.lost} thua · ${d.win_rate===null?'Chưa có tỷ lệ thắng':d.win_rate+'% tỷ lệ thắng'}</p>`:pending.length?pending.map(q=>`<div class="activity-row"><div class="grow"><a href="#/quote/${q.id}"><strong>${esc(q.code)} · v${q.version}</strong><small>${esc(q.customer_name)}</small></a></div>${tag('PENDING')}</div>`).join(''):empty('Chưa có báo giá chờ bạn duyệt',me.role==='admin'?'Bạn có thể chuẩn bị mẫu và cấu hình công ty.':'Báo giá vượt ngưỡng sẽ xuất hiện ở đây.')}</section><section class="card"><div class="section-heading"><div><h3>${writable()?'Lịch hẹn & công việc':'Thiết lập và kiểm thử'}</h3><p>${writable()?'Những việc đến hạn hoặc chưa hoàn tất.':'Các bước chuẩn bị để đội sales dùng thử.'}</p></div>${writable()?'<button id="new-task" class="circle-action" aria-label="Thêm công việc">+</button>':''}</div>${writable()?upcoming.map(t=>`<div class="activity-row"><span class="when ${late(t)?'overdue':''}">${late(t)?'Quá hạn<br>':''}${esc(dueText(t.due_at))}</span><div class="grow"><a href="#/tasks/${t.id}"><strong>${esc(t.title)}</strong><small>${esc(t.customer_name||'Việc nội bộ')} · ${esc(t.kind||'Công việc')}</small></a></div><button class="circle-action" data-complete="${t.id}" aria-label="Hoàn thành ${esc(t.title)}">✓</button></div>`).join('')||empty('Chưa có việc cần xử lý','Tạo kế hoạch từ hồ sơ khách hàng.'):me.role==='admin'?'<div class="activity-row"><a href="#/settings">Cấu hình lịch làm việc →</a></div><div class="activity-row"><a href="#/templates">Chuẩn bị mẫu báo giá và nhận diện →</a></div><div class="activity-row"><a href="#/users">Chuyên môn và tài khoản nhân viên →</a></div>':'<div class="activity-row"><a href="#/knowledge">Kiểm tra nội dung FAQ chờ duyệt →</a></div><div class="activity-row"><a href="#/guide">Xem kịch bản nghiệm thu →</a></div>'}${writable()?'<p style="margin:20px 0 0"><a href="#/tasks" class="small">Xem tất cả kế hoạch →</a></p>':''}</section><section class="card"><div class="section-heading"><div><h3>Cuộc trò chuyện gần đây</h3><p>Những hội thoại trong phạm vi bạn phụ trách.</p></div>${writable()?'<a href="#/inbox">Mở hộp thư →</a>':''}</div>${conversations.slice(0,3).map(c=>`<a class="activity-row" href="#/conversation/${c.id}" style="text-decoration:none;color:inherit">${avatar(c.customer_name,'peach')}<div class="grow"><strong>${esc(c.customer_name)}</strong><small>${esc((c.last_body||'Chưa có tin nhắn').slice(0,85))}</small></div><span class="channel-chip">${channelName(c.channel)}</span></a>`).join('')||empty('Chưa có hội thoại trong phạm vi')}</section><section class="card ready-card"><div class="mini-label">BOT & KÊNH KẾT NỐI</div><h3>Thử quy trình, theo dõi đúng trạng thái</h3><p class="small">Bot FAQ dùng nội dung đã được giám đốc duyệt. Zalo OA có phần cấu hình kết nối; Zalo cá nhân vẫn mô phỏng. AI tạo sinh chưa kết nối.</p><div class="actions"><a href="#/knowledge">Nội dung bot →</a><a href="#/channels">Xem kênh →</a></div></section></div></div>`);
 action(el,'#create',()=>form('Tạo mới',[['type','Bạn muốn tạo','select',[['customer','Khách hàng'],['opportunity','Cơ hội bán hàng'],['quote','Báo giá'],['task','Kế hoạch tiếp xúc']]]],async v=>{if(v.type==='customer'){go('#/customers/new');}else if(v.type==='opportunity')setTimeout(()=>newOpportunity(),0);else if(v.type==='quote')setTimeout(()=>newQuote(),0);else setTimeout(()=>planTask(),0);}));
 action(el,'#new-task',()=>planTask());action(el,'[data-complete]',async b=>{await api('/tasks/'+b.dataset.complete+'/done',{body:{}});render();});return el;
};

views.customers=async routeId=>{
 const list=await api('/customers');let kind='all',care='all';const owners=[...new Map(list.filter(c=>c.owner_id).map(c=>[c.owner_id,c.owner_name])).entries()];
 const el=$(`<div>${pageHeading('Danh bạ khách hàng','Hồ sơ, hội thoại và hành trình bán hàng trong cùng một nơi.',`<button class="major" id="new">${icon('plus')} Thêm khách hàng</button>${me.role==='leader'?'<button id="import">Nhập CSV</button>':''}`)}<div class="compact-counts"><div><strong>${list.length}</strong>khách trong phạm vi</div><div><strong>${list.filter(c=>c.kind==='org').length}</strong>tổ chức</div><div><strong>${list.filter(c=>c.kind==='person').length}</strong>cá nhân</div><div><strong>${list.filter(c=>!c.owner_id).length}</strong>chờ phân công</div></div><div class="segments" role="tablist" aria-label="Loại khách hàng">${[['all','Tất cả'],['org','Tổ chức'],['person','Cá nhân']].map(([k,n])=>`<button data-kind="${k}" role="tab" aria-selected="${k==='all'}" class="${k==='all'?'selected':''}">${n}</button>`).join('')}</div><section class="card table-card"><div class="filterbar"><input id="search" type="search" placeholder="Tìm khách, điện thoại, email…" aria-label="Tìm khách hàng"><select id="owner" aria-label="Người phụ trách">${options([['all','Tất cả người phụ trách'],['none','Chưa phân công'],...owners],'all')}</select><select id="care" aria-label="Tình trạng chăm sóc">${options([['all','Tất cả tình trạng'],['followup','Cần tiếp tục xử lý'],['no-contact','Không liên hệ']],'all')}</select></div><table><thead><tr><th>Khách hàng</th><th>Liên hệ</th><th>Dịch vụ quan tâm</th><th>Chăm sóc</th><th>Phụ trách</th></tr></thead><tbody></tbody></table><div class="list-meta"></div></section></div>`);
 const fill=()=>{const search=searchFold(el.querySelector('#search').value),owner=el.querySelector('#owner').value;const rows=list.filter(c=>(kind==='all'||c.kind===kind)&&(owner==='all'||owner==='none'&&!c.owner_id||String(c.owner_id)===owner)&&(care==='all'||care==='followup'&&c.needs_followup||care==='no-contact'&&c.do_not_contact)&&[c.name,c.phone,c.email,c.interest].join(' ').toLocaleLowerCase('vi').includes(search));el.querySelector('tbody').innerHTML=rows.map(c=>`<tr><td><div class="identity">${avatar(c.name,c.kind==='org'?'purple':'peach')}<div><a href="#/customer/${c.id}"><strong>${esc(c.name)}</strong></a><small>${c.kind==='person'?'Cá nhân':esc(c.org_type||'Tổ chức')} · ${c.is_sample?'Mẫu':'Dữ liệu nhập'}</small></div></div></td><td>${esc(c.phone||'—')}<small style="display:block">${esc(c.email||'')}</small></td><td>${esc(c.interest||'Chưa ghi nhận')}</td><td>${c.do_not_contact?tag('Không liên hệ'):tag(c.needs_followup?'Cần xử lý':'Đã xử lý')}</td><td>${esc(c.owner_name||'Chờ phân công')}</td></tr>`).join('')||'<tr><td colspan="5">Không có khách hàng phù hợp.</td></tr>';el.querySelector('.list-meta').textContent=`Hiển thị ${rows.length} / ${list.length} khách trong phạm vi của bạn`;};fill();
 el.querySelector('#search').oninput=fill;el.querySelector('#owner').onchange=fill;el.querySelector('#care').onchange=e=>{care=e.target.value;fill();};action(el,'[data-kind]',b=>{kind=b.dataset.kind;el.querySelectorAll('[data-kind]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-selected',String(x===b));});fill();});
 const create=()=>form('Thêm khách hàng',[['kind','Loại khách','select',[['org','Tổ chức / cơ quan'],['person','Cá nhân']]],...customerFields(),['is_sample','Đây là dữ liệu mẫu','check',null,true]],async v=>{const r=await api('/customers',{body:v});if(r.duplicate_warning)toast(r.duplicate_warning);go('#/customer/'+r.id);});action(el,'#new',create);action(el,'#import',()=>go('#/import'));if(routeId==='new')setTimeout(create,0);return el;
};

async function planTask(customer=null,task=null,after=null){
 const [customers,users]=await Promise.all([customer?Promise.resolve([customer]):api('/customers'),api('/users')]);
 const localDate=task?.due_at?new Date(Date.parse(task.due_at)+7*3600000).toISOString().slice(0,16):'';
 const fields=[['title','Tên việc / mục đích tiếp xúc *','text',null,task?.title],['kind','Loại tiếp xúc','select',[['Công việc','Công việc'],['Cuộc gọi','Cuộc gọi'],['Cuộc họp','Cuộc họp'],['Demo','Demo']],task?.kind],['priority','Mức ưu tiên','select',[['Bình thường','Bình thường'],['Cao','Cao']],task?.priority],['due_at','Ngày giờ (giờ Việt Nam)','datetime-local',null,localDate],['note','Nội dung chuẩn bị','textarea',null,task?.note]];
 if(!task){fields.splice(1,0,['customer_id','Khách hàng','select',customer?[[customer.id,customer.name]]:[['','Việc nội bộ'],...customers.map(c=>[c.id,c.name])],customer?.id]);if(me.role==='leader')fields.push(['assignee_id','Giao cho','select',[['','Theo người phụ trách khách'],...users.filter(u=>['sales','leader'].includes(u.role)).map(u=>[u.id,u.name])]]);}
 form(task?'Cập nhật kế hoạch':'Lên kế hoạch tiếp xúc',fields,async v=>{v.due_at=v.due_at?new Date(v.due_at+':00+07:00').toISOString():null;const result=await api('/tasks'+(task?'/'+task.id:''),{method:task?'PUT':'POST',body:v});toast(task?'Đã cập nhật kế hoạch.':'Đã tạo kế hoạch tiếp xúc.');if(after)await after();else if(location.hash.startsWith('#/tasks'))render();else go('#/tasks/'+(task?.id||result.id));});
}
async function renderCustomerPlans(box,customer){
 const pane=$('<section data-customer-plans><p role="status">Đang tải kế hoạch tiếp xúc…</p></section>');box.replaceChildren(pane);
 const refresh=()=>renderCustomerPlans(box,customer);
 try{const tasks=await api('/customers/'+customer.id+'/tasks');if(!box.contains(pane))return;
  pane.innerHTML=`<div class="section-heading"><div><h3>Kế hoạch tiếp xúc (${tasks.length})</h3><p class="small">Khách hàng: ${esc(customer.name)} · Cùng dữ liệu với mục Kế hoạch tiếp xúc.</p></div><div class="actions"><button data-plan-refresh>Làm mới</button>${!customer.archived_at?'<button data-plan-add class="major">+ Thêm kế hoạch</button>':''}</div></div>${tasks.map(t=>`<div class="task-row"><div class="grow"><button class="task-title" data-plan-open="${t.id}"><strong>${esc(t.title)}</strong></button><small>Người thực hiện: ${esc(t.assignee_name||'Chưa phân công')}</small><small>Ngày tạo: ${esc(taskCreatedText(t.created_at))}</small><small>Hạn thực hiện: ${esc(dueText(t.due_at))}</small>${t.note?`<p class="small preserve">${esc(t.note)}</p>`:''}</div>${tag(t.kind||'Công việc')}${tag(t.status)}${late(t)?tag('Quá hạn'):''}<button data-plan-edit="${t.id}">Sửa</button><button data-plan-done="${t.id}">${t.status==='COMPLETED'?'Mở lại':'Hoàn thành'}</button></div>`).join('')||empty('Chưa có kế hoạch gắn với khách này','Bấm Thêm kế hoạch để tạo việc cho đúng khách hàng.')}<p class="small">Công việc nội bộ và công việc của khách khác không xuất hiện trong hồ sơ này.</p>`;
  action(pane,'[data-plan-refresh]',refresh);action(pane,'[data-plan-add]',()=>planTask(customer,null,refresh));action(pane,'[data-plan-open]',b=>openContactPlan(tasks.find(t=>String(t.id)===b.dataset.planOpen),refresh));action(pane,'[data-plan-edit]',b=>planTask(customer,tasks.find(t=>String(t.id)===b.dataset.planEdit),refresh));action(pane,'[data-plan-done]',async b=>{const t=tasks.find(t=>String(t.id)===b.dataset.planDone);await api('/tasks/'+t.id+(t.status==='COMPLETED'?'/reopen':'/done'),{body:{}});await refresh();});
 }catch(e){if(box.contains(pane)){pane.innerHTML=`<p class="err">${esc(e.message)}</p><button data-plan-retry>Thử lại</button>`;action(pane,'[data-plan-retry]',refresh);}}
}
views.customer=async id=>{
 const [d,timeline,notes,users]=await Promise.all([api('/customers/'+id),api('/customers/'+id+'/timeline'),api('/customers/'+id+'/notes'),api('/users')]),c=d.customer;
 const el=$(`<div>${pageHeading(c.name,'Một hồ sơ xuyên suốt quá trình chăm sóc và bán hàng.',`<button id="edit">Chỉnh sửa hồ sơ</button>${me.role==='leader'&&!c.owner_id?'<button id="assign" class="major">Phân công</button>':''}`)}<div class="profile-grid"><section class="card profile-summary"><span class="avatar large peach">${esc(initials(c.name))}</span><h3>${esc(c.name)}</h3><p class="small">${c.kind==='person'?'Khách hàng cá nhân':esc(c.org_type||'Tổ chức')}</p>${tag(c.has_pkg1?'Đã đăng ký Gói 1':'Chưa đăng ký Gói 1')}<div class="profile-actions"><button id="conv">${icon('chat')} Hội thoại</button><button id="plan">${icon('calendar')} Lên lịch</button><button id="opp">${icon('sales')} Cơ hội</button><button id="quote">${icon('quote')} Báo giá</button></div><div style="margin-top:22px">${[['Phụ trách',c.owner_name||'Chưa phân công'],['Điện thoại',c.phone||'—'],['Email',c.email||'—'],['Dịch vụ',c.interest||'Chưa ghi nhận'],['Chăm sóc',c.do_not_contact?'Không liên hệ':c.needs_followup?'Cần tiếp tục xử lý':'Đã xử lý']].map(([label,value])=>`<div class="balance"><span>${label}</span><span>${esc(value)}</span></div>`).join('')}</div></section><section class="card"><div class="segments profile-tabs" role="tablist" aria-label="Nội dung hồ sơ">${[['timeline','Lịch sử tương tác'],['sales','Cơ hội & báo giá'],['plans','Kế hoạch'],['notes','Ghi chú']].map(([key,label])=>`<button data-tab="${key}" role="tab" aria-selected="${key==='timeline'}" class="${key==='timeline'?'selected':''}">${label}</button>`).join('')}</div><div class="profile-tab-content"></div><div style="border-top:1px solid var(--line);padding-top:20px"><label for="note" class="small">Ghi chú cho lần tiếp xúc tiếp theo</label><div class="event-note"><textarea id="note" placeholder="Nhu cầu, kết quả tư vấn, điều cần chuẩn bị…"></textarea><button class="major" id="add-note">Lưu ghi chú</button></div></div></section></div></div>`);
 const fill=tab=>{const box=el.querySelector('.profile-tab-content');if(tab==='timeline')box.innerHTML=`<div class="timeline">${timeline.events.map(e=>`<div class="timeline-item">${e.href?`<a href="${e.href}">${esc(String(e.id).startsWith('work:')?taskHistoryText(e.title):e.title)}</a>`:`<strong>${esc(String(e.id).startsWith('work:')?taskHistoryText(e.title):e.title)}</strong>`}<small>${esc(e.type)} · ${dt(e.at)}${e.actor?' · '+esc(e.actor):''}</small>${e.detail?`<p>${esc(e.detail)}</p>`:''}</div>`).join('')}</div>`;else if(tab==='sales')box.innerHTML=`<h3>Cơ hội bán hàng</h3>${d.opportunities.map(o=>`<a class="activity-row" href="#/opportunity/${o.id}" style="color:inherit;text-decoration:none"><div class="grow"><strong>${esc(o.title)}</strong><small>${vnd(o.est_value)}</small></div>${tag(o.stage)}</a>`).join('')||empty('Chưa có cơ hội')}<h3 style="margin-top:25px">Báo giá</h3>${d.quotes.map(q=>`<a class="activity-row" href="#/quote/${q.id}" style="color:inherit;text-decoration:none"><div class="grow"><strong>${esc(q.code)} · v${q.version}</strong></div>${tag(q.status)}</a>`).join('')||empty('Chưa có báo giá')}`;else if(tab==='plans')renderCustomerPlans(box,c);else box.innerHTML=notes.map(n=>`<div class="readystate preserve">${esc(n.body)}<div class="small">${esc(n.user_name)} · ${dt(n.at)}</div></div>`).join('')||empty('Chưa có ghi chú');};fill('timeline');
 action(el,'[data-tab]',b=>{el.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-selected',String(x===b));});fill(b.dataset.tab);});
 action(el,'#edit',()=>form('Sửa khách hàng',customerFields(c),async v=>{await api('/customers/'+id,{method:'PUT',body:v});render();}));action(el,'#assign',()=>form('Giao khách cho sales',[['user_id','Sales trong nhóm','select',users.filter(u=>u.role==='sales').map(u=>[u.id,u.name])]],async v=>{await api(`/customers/${id}/assign`,{body:v});render();}));action(el,'#add-note',async()=>{await api(`/customers/${id}/notes`,{body:{body:el.querySelector('#note').value}});render();});action(el,'#plan',()=>planTask(c));action(el,'#opp',()=>newOpportunity(c));action(el,'#quote',()=>newQuote(c));action(el,'#conv',()=>form('Mở hội thoại',[['channel','Kênh thử','select',[['oa','Zalo OA'],['personal','Zalo cá nhân công ty']]]],async v=>{const r=await api('/conversations',{body:{...v,customer_id:c.id}});go('#/conversation/'+r.id);}));return el;
};

function changeOpportunityStage(o,to,after=render){
 if(o.stage==='Thua')return reopenOpportunity(o,after,to);
 if(o.stage===to)return;if(o.stage==='Thắng'){toast('Cơ hội đã thắng được giữ nguyên trong bản thử.');return;}
 if(o.stage==='Thua'&&to==='Thắng'){toast('Mở lại về một bước đang xử lý trước khi ghi nhận thắng.');return;}
 const fields=[];if(to==='Thắng')fields.push(['contract_signed','Xác nhận hai bên đã ký hợp đồng','check'],['final_value','Giá trị chốt (VNĐ)','number',null,o.est_value],['closed_at','Ngày chốt','date']);
 if(to==='Thua')fields.push(['reason','Lý do thua *','textarea']);else if(o.stage==='Thua')fields.push(['reason','Lý do mở lại *','textarea']);
 const send=async v=>{await api('/opportunities/'+o.id+'/stage',{body:{to,...v}});toast('Đã chuyển cơ hội sang '+to+'.');await after();};
 if(fields.length)form('Chuyển sang '+to,fields,send);else send({}).catch(e=>toast(e.message));
}
function reopenOpportunity(o,after=render,target='Mới'){
 const choices=STAGES.filter(s=>!['Thắng','Thua'].includes(s));
 form('Mở lại cơ hội · '+o.title,[['to','Giai đoạn tiếp tục','select',choices.map(s=>[s,s]),choices.includes(target)?target:choices[0]],['reason','Lý do mở lại *','textarea']],async body=>{await api('/opportunities/'+o.id+'/stage',{body});toast('Đã mở lại cơ hội; lịch sử cũ được giữ nguyên.');await after();});
}
views.pipeline=async()=>{
 const list=await api('/opportunities');const el=$(`<div>${pageHeading('Cơ hội bán hàng','Theo dõi từng bước, từ nhu cầu đến hợp đồng đã ký.',`<button class="major" id="new">${icon('plus')} Tạo cơ hội</button>`)}<section class="card"><div class="filterbar"><strong style="flex:1">Tổng chưa lọc: ${list.length} cơ hội</strong><input id="search" type="search" placeholder="Tìm tên cơ hội, khách hàng…" aria-label="Tìm cơ hội"><select id="stage-filter" aria-label="Lọc giai đoạn">${options([['all','Tất cả giai đoạn'],...STAGES.map(s=>[s,s])],'all')}</select></div><p class="small">Số lượng và giá trị ở mỗi cột tính theo bộ lọc hiện tại. Kéo thẻ hoặc mở cơ hội để chuyển bước. Thắng cần xác nhận hai bên ký; thua và mở lại cần lý do.</p><div class="pipeline-scroll"><div class="kanban"></div></div></section></div>`);
 const fill=()=>{const search=el.querySelector('#search').value.toLocaleLowerCase('vi'),filter=el.querySelector('#stage-filter').value;const filtered=list.filter(o=>searchFold(o.title+' '+o.customer_name).includes(search));el.querySelector('.kanban').innerHTML=STAGES.filter(s=>filter==='all'||s===filter).map(s=>{const rows=filtered.filter(o=>o.stage===s),idx=STAGES.indexOf(s);return `<section class="kanban-lane" data-stage="${esc(s)}" style="--stage-color:${stageColors[idx]}"><div class="kanban-title"><span>${esc(s)}</span><b>${rows.length}</b></div><div class="lane-value">${vnd(rows.reduce((n,o)=>n+(s==='Thắng'?o.final_value:o.est_value),0))}</div>${rows.map(o=>`<a class="kanban-card" href="#/opportunity/${o.id}" draggable="${o.stage!=='Thắng'}" data-opp="${o.id}"><span class="tag">${o.kind==='person'?'Khách cá nhân':'Tổ chức'}</span><h4>${esc(o.title)}</h4><small>${esc(o.customer_name)}</small><span class="value">${vnd(s==='Thắng'?o.final_value:o.est_value)}</span><small>${esc(o.owner_name||'Chưa phân công')}</small><div class="card-foot"><span>${icon('calendar')} ${o.expected_close?new Date(o.expected_close).toLocaleDateString('vi-VN'):'Chưa hẹn chốt'}</span>${avatar(o.owner_name)}</div></a>`).join('')||empty('Chưa có cơ hội')}</section>`;}).join('');
 el.querySelectorAll('[data-opp]').forEach(card=>card.ondragstart=e=>{e.dataTransfer.setData('text/plain',card.dataset.opp);e.dataTransfer.effectAllowed='move';});el.querySelectorAll('[data-stage]').forEach(lane=>{lane.ondragover=e=>{e.preventDefault();lane.classList.add('drop-target');};lane.ondragleave=()=>lane.classList.remove('drop-target');lane.ondrop=e=>{e.preventDefault();lane.classList.remove('drop-target');const o=list.find(x=>String(x.id)===e.dataTransfer.getData('text/plain'));if(o)changeOpportunityStage(o,lane.dataset.stage);};});};fill();el.querySelector('#search').oninput=fill;el.querySelector('#stage-filter').onchange=fill;action(el,'#new',()=>newOpportunity());return el;
};
newQuote=async function(c,opportunity=null){const [cs,t]=await Promise.all([c?Promise.resolve([c]):api('/customers'),api('/templates')]);form('Lập báo giá'+(opportunity?' cho cơ hội':''),[['customer_id','Khách hàng','select',cs.map(c=>[c.id,c.name]),c?.id],['template_id','Mẫu báo giá','select',t.templates.map(t=>[t.id,t.name])]],async v=>{const r=await api('/quotes',{body:{...v,opp_id:opportunity?.id||null}});go('#/quote/'+r.id);});};
views.opportunity=async id=>{
 const d=await api('/opportunities/'+id),o=d.opportunity,c=d.customer;const customer=await api('/customers/'+c.id),related=customer.quotes;const el=$(`<div>${pageHeading(o.title,c.name,`<button id="plan">${icon('calendar')} Lên lịch</button><button class="major" id="quote">${icon('plus')} Lập báo giá</button>`)}<div class="stepper">${STAGES.map(s=>`<button data-s="${esc(s)}" class="${s===o.stage?'current':''}" ${s===o.stage||o.stage==='Thắng'?'disabled':''}>${esc(s)}</button>`).join('')}</div><div class="detail-grid"><section class="card"><div class="section-heading"><h3>Lịch sử hành trình</h3>${tag(o.stage)}</div>${o.stage==='Thua'?`<div class="notice">Lý do thua: ${esc(o.lost_reason)} <button id="reopen-opportunity" class="major">Mở lại cơ hội</button></div>`:''}${o.stage==='Thắng'?`<div class="quoted-state">Hai bên đã ký hợp đồng · ${vnd(o.final_value)} · ${dt(o.closed_at)}</div>`:''}<div class="timeline">${[...d.history].reverse().map(h=>`<div class="timeline-item"><strong>${esc(h.from_stage||'Bắt đầu')} → ${esc(h.to_stage)}</strong><small>${dt(h.at)} · ${esc(h.user_name||'')}</small>${h.reason?`<p>${esc(h.reason)}</p>`:''}</div>`).join('')}</div></section><aside><section class="card"><div class="identity">${avatar(c.name,'peach')}<div><a href="#/customer/${c.id}"><strong>${esc(c.name)}</strong></a><small>Mở hồ sơ khách hàng →</small></div></div><div class="balance" style="margin-top:20px"><span>Giá trị dự kiến</span><strong>${vnd(o.est_value)}</strong></div><div class="balance"><span>Ngày chốt dự kiến</span>${o.expected_close?new Date(o.expected_close).toLocaleDateString('vi-VN'):'Chưa đặt'}</div></section><section class="card"><h3>Báo giá của khách</h3>${related.map(q=>`<a class="activity-row" href="#/quote/${q.id}"><div class="grow"><strong>${esc(q.code)} · v${q.version}</strong></div>${tag(q.status)}</a>`).join('')||empty('Chưa có báo giá','Báo giá mới được gắn với cơ hội này.')}</section></aside></div></div>`);action(el,'#reopen-opportunity',()=>reopenOpportunity(o));action(el,'[data-s]',b=>changeOpportunityStage(o,b.dataset.s));action(el,'#quote',()=>newQuote(c,o));action(el,'#plan',()=>planTask(c,null,null,{opp_id:o.id,contact_id:o.contact_id}));return el;
};

function openContactPlan(t,after=render){const dlg=$(`<dialog class="task-detail"><div class="section-heading"><h3>${esc(t.title)}</h3><button id="dismiss" aria-label="Đóng">×</button></div><p>${tag(t.status)} ${tag(t.kind||'Công việc')} ${t.priority==='Cao'?tag('Ưu tiên cao'):''}</p><dl class="task-detail-meta"><div><dt>Khách hàng liên quan</dt><dd>${t.customer_id?`<a href="#/customer/${t.customer_id}">${esc(t.customer_name)}</a>`:'Việc nội bộ'}</dd></div><div><dt>Ngày tạo công việc</dt><dd>${esc(taskCreatedText(t.created_at))}</dd></div><div><dt>Thời hạn</dt><dd>${dueText(t.due_at)} ${late(t)?tag('Quá hạn'):''}</dd></div><div><dt>Người thực hiện</dt><dd>${esc(t.assignee_name||'Chưa phân công')}</dd></div></dl><section class="task-description"><h4>Mô tả / Nội dung chuẩn bị</h4><p class="preserve">${esc(t.note||'Chưa có ghi chú chuẩn bị.')}</p></section><div class="actions"><button id="edit">Chỉnh sửa</button><button id="complete" class="major">${t.status==='COMPLETED'?'Mở lại công việc':'Đánh dấu hoàn thành'}</button></div></dialog>`);document.body.append(dlg);dlg.showModal();dlg.onclose=()=>dlg.remove();dlg.querySelector('#dismiss').onclick=()=>dlg.close();dlg.querySelector('a')?.addEventListener('click',()=>dlg.close());action(dlg,'#edit',()=>{dlg.close();planTask(null,t,after);});action(dlg,'#complete',async()=>{await api('/tasks/'+t.id+(t.status==='COMPLETED'?'/reopen':'/done'),{body:{}});dlg.close();after();});};
views.tasks=async taskId=>{
 const [list,customers]=await Promise.all([api('/tasks'),api('/customers')]);const closedGroups=new Set();let filter='all',mode='list',offset=0;const today=vietnamDay(Date.now());const el=$(`<div>${pageHeading('Kế hoạch tiếp xúc','Công việc được chia theo từng đơn vị / khách hàng. Mở từng mục để theo dõi và thêm việc.',`<button id="new" class="major">${icon('plus')} Lên lịch tiếp xúc</button>`)}<div class="compact-counts"><div><strong>${list.filter(t=>t.status!=='COMPLETED'&&t.due_at&&vietnamDay(t.due_at)===today).length}</strong>việc hôm nay</div><div><strong>${list.filter(late).length}</strong>việc quá hạn</div><div><strong>${list.filter(t=>t.status==='COMPLETED').length}</strong>đã hoàn thành</div></div><section class="card"><div class="filterbar"><div class="segments" style="flex:1;margin:0">${[['all','Tất cả'],['today','Hôm nay'],['overdue','Quá hạn'],['done','Đã hoàn thành']].map(([f,label])=>`<button data-filter="${f}" class="${f==='all'?'selected':''}">${label}</button>`).join('')}</div><div class="segments" style="margin:0"><button data-mode="list" class="selected">Theo đơn vị</button><button data-mode="week">Lịch tuần</button></div></div><div id="task-content"></div></section></div>`);
 const openTask=t=>openContactPlan(t);
 const filtered=()=>list.filter(t=>filter==='all'||filter==='today'&&t.due_at&&vietnamDay(t.due_at)===today||filter==='overdue'&&late(t)||filter==='done'&&t.status==='COMPLETED');
 const fill=()=>{const rows=filtered(),box=el.querySelector('#task-content');if(mode==='list'){
 const groups=new Map();for(const t of rows){const key=String(t.customer_id||'internal');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t);}
 box.innerHTML=[...groups].map(([key,tasks])=>{
 const c=customers.find(c=>String(c.id)===key),all=list.filter(t=>String(t.customer_id||'internal')===key),done=all.filter(t=>t.status==='COMPLETED').length,percent=Math.round(done*100/all.length),name=c?.name||tasks[0].customer_name||'Việc nội bộ';
 return `<details class="task-unit" data-unit="${esc(key)}" ${closedGroups.has(key)?'':'open'}><summary><div class="task-unit-name"><strong>${esc(name)}</strong><small>${esc(c?.owner_name?'Phụ trách: '+c.owner_name:key==='internal'?'Không gắn với khách hàng':'Chưa phân công người phụ trách')} · ${all.length} công việc</small></div>${tag(done===all.length?'COMPLETED':'Đang xử lý')}<span class="task-unit-percent" style="--percent:${percent}%" aria-label="Hoàn thành ${percent}%"><span>${percent}%</span></span><span class="task-unit-chevron" aria-hidden="true">⌃</span></summary><div class="task-unit-body"><div class="section-heading"><div><h3>Công việc (${tasks.length})</h3><small>Đã hoàn thành ${done}/${all.length} việc · Tỷ lệ tính trên toàn bộ việc của đơn vị trong phạm vi được xem.</small></div><div class="actions">${c?`<a href="#/customer/${c.id}">Hồ sơ đơn vị →</a><button data-unit-add="${c.id}">+ Thêm việc</button>`:key==='internal'?'<button data-unit-add="internal">+ Thêm việc</button>':''}</div></div>${tasks.map(t=>`<div class="task-row ${t.status==='COMPLETED'?'done':''}" data-search="${esc(name+' '+t.title+' '+(t.assignee_name||'')+' '+(t.note||''))}"><button class="circle-action" data-done="${t.id}" aria-label="${t.status==='COMPLETED'?'Mở lại':'Hoàn thành'} ${esc(t.title)}">${t.status==='COMPLETED'?'✓':'○'}</button><div class="grow"><button class="task-title" data-open="${t.id}"><strong>${esc(t.title)}</strong></button><small>Người thực hiện: ${esc(t.assignee_name||'Chưa phân công')}</small><small>Ngày tạo: ${esc(taskCreatedText(t.created_at))}</small><small class="task-due">Hạn thực hiện: ${esc(dueText(t.due_at))}</small></div>${tag(t.kind||'Công việc')}${tag(t.status==='COMPLETED'?'COMPLETED':'Đang xử lý')}${late(t)?tag('Quá hạn'):''}${t.priority==='Cao'?'<span class="task-priority">↑ Ưu tiên cao</span>':''}</div>`).join('')}</div></details>`;
 }).join('')||empty('Không có kế hoạch phù hợp','Tạo kế hoạch từ hồ sơ khách hoặc nút Lên lịch tiếp xúc.');
 box.querySelectorAll('.task-unit').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)closedGroups.delete(d.dataset.unit);else closedGroups.add(d.dataset.unit);}));
 action(box,'[data-unit-add]',b=>planTask(b.dataset.unitAdd==='internal'?null:customers.find(c=>String(c.id)===b.dataset.unitAdd)));
 }else{const start=new Date(today+'T00:00:00+07:00');const day=new Date(Date.parse(today+'T00:00:00Z')).getUTCDay();start.setTime(start.getTime()+((day===0?-6:1-day)+offset*7)*86400000);const days=Array.from({length:7},(_,i)=>new Date(start.getTime()+i*86400000));box.innerHTML=`<div class="section-heading"><button id="week-before">← Tuần trước</button><span class="small">${days[0].toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})} – ${days[6].toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})}</span><button id="week-after">Tuần sau →</button></div><div style="overflow:auto"><div class="calendar-grid">${days.map(day=>{const dayKey=vietnamDay(day),matches=rows.filter(t=>t.due_at&&vietnamDay(t.due_at)===dayKey);return `<section class="calendar-day ${dayKey===today?'today':''}"><h4>${day.toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',weekday:'short',day:'2-digit',month:'2-digit'})}</h4>${matches.map(t=>`<button class="calendar-event" data-open="${t.id}" style="text-align:left;width:100%"><strong>${esc(t.title)}</strong><small>${dueText(t.due_at)}<br>${esc(t.customer_name||'Nội bộ')}</small></button>`).join('')||'<small>Chưa có lịch</small>'}</section>`;}).join('')}</div></div><p class="small">${rows.filter(t=>!t.due_at).length} công việc chưa đặt thời gian có trong chế độ Danh sách.</p>`;action(box,'#week-before',()=>{offset--;fill();});action(box,'#week-after',()=>{offset++;fill();});}action(box,'[data-open]',b=>openTask(list.find(t=>String(t.id)===b.dataset.open)));action(box,'[data-done]',async b=>{const t=list.find(t=>String(t.id)===b.dataset.done);await api('/tasks/'+t.id+(t.status==='COMPLETED'?'/reopen':'/done'),{body:{}});render();});};fill();action(el,'#new',()=>planTask());action(el,'[data-filter]',b=>{filter=b.dataset.filter;el.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));fill();});action(el,'[data-mode]',b=>{mode=b.dataset.mode;el.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));fill();});if(taskId){const selected=list.find(t=>String(t.id)===taskId);if(selected)setTimeout(()=>{if(!document.querySelector('dialog'))openTask(selected);},0);}return el;
};

const inboxFilters={term:'',channel:'all',status:'open'};
async function inboxWorkspace(id){
 const list=await api('/conversations');const matches=v=>(inboxFilters.channel==='all'||channelId(v.channel)===inboxFilters.channel)&&(inboxFilters.status==='all'||inboxFilters.status==='open'&&v.status==='OPEN'||inboxFilters.status==='closed'&&v.status==='CLOSED'||inboxFilters.status==='waiting'&&!v.assignee_id||inboxFilters.status==='bot'&&v.bot_active)&&[v.customer_name,v.last_body].join(' ').toLocaleLowerCase('vi').includes(inboxFilters.term.toLocaleLowerCase('vi'));
 const selected=id?list.find(v=>String(v.id)===String(id)):list.find(matches);if(id&&!selected)throw Error('Hội thoại ngoài phạm vi được xem.');
 const d=selected?await api('/conversations/'+selected.id):null,c=d?.customer,v=d?.conversation;let composer='reply';
 const related=c?await api('/customers/'+c.id):null;
 const el=$(`<div>${pageHeading('Hộp thư Zalo','Hội thoại và thông tin khách hàng trong cùng một không gian.',`<span class="tag quiet">Nhận/gửi mô phỏng</span>`)}<div class="inbox-frame"><aside class="conversation-list"><div class="list-controls"><input type="search" id="conversation-search" aria-label="Tìm hội thoại" placeholder="Tìm cuộc trò chuyện…" value="${esc(inboxFilters.term)}"><div class="segments">${[['all','Tất cả'],['oa','Zalo OA'],['personal','Cá nhân']].map(([value,label])=>`<button data-channel="${value}" class="${inboxFilters.channel===value?'selected':''}">${label}</button>`).join('')}</div><select id="conversation-status" aria-label="Lọc hội thoại">${options([['open','Đang mở & cần xử lý'],['all','Tất cả hội thoại'],['waiting','Chờ trưởng nhóm giao'],['bot','Bot đang hỗ trợ'],['closed','Đã đóng']],inboxFilters.status)}</select></div><div class="inbox-list"></div></aside>${d?`<section class="chat-pane"><header class="chat-header"><div class="identity">${avatar(c.name,'peach')}<div><h3>${esc(c.name)}</h3><p><span class="channel-chip">${channelName(v.channel)}</span> · <a href="#/customer/${c.id}">Hồ sơ khách hàng</a></p></div></div>${v.assignee_id?`<button id="close">${v.status==='CLOSED'?'Mở lại':'Giải quyết'}</button>`:''}</header><div class="chat-actions"><span>${v.bot_active?'Bot FAQ đang hỗ trợ':'Nhân viên: '+esc(selected.assignee_name||'Chưa phân công')}</span>${v.assignee_id?`<button id="bot">${v.bot_active?'Tiếp nhận · dừng bot':'Chuyển lại cho bot'}</button>`:'<span>Chờ phân công</span>'}</div><div class="thread">${d.messages.map(m=>{let meta={};try{meta=JSON.parse(m.metadata||'{}');}catch{}return `<div class="msg ${['agent','customer','bot','system'].includes(m.sender)?m.sender:'system'}">${m.sender!=='system'?`<small>${m.sender==='customer'?'Khách thử':m.sender==='bot'?'Bot FAQ':esc(m.user_name||'Nhân viên')} · ${dt(m.at)}</small>`:''}${esc(m.body)}${meta.source?`<small style="margin:8px 0 0">Nguồn: ${esc(meta.source.title)} · v${meta.source.version}</small>`:''}</div>`;}).join('')||'<div class="empty">Chưa có tin nhắn</div>'}</div><section class="composer"><div class="segments"><button data-composer="reply" class="selected">Trả lời qua ${channelName(v.channel)}</button><button data-composer="note">Ghi chú nội bộ</button></div><textarea id="reply" aria-label="Nội dung soạn" placeholder="Nhập phản hồi cho khách…" ${!v.assignee_id||v.status==='CLOSED'?'disabled':''}></textarea><div class="composer-footer"><button id="test-message">Tin nhắn thử nghiệm</button><small id="composer-hint">Chỉ lưu trong CRM, chưa gửi thật.</small><button class="major" id="send" ${!v.assignee_id||v.status==='CLOSED'?'disabled':''}>Gửi thử</button></div></section></section><aside class="customer-aside"><div class="person"><span class="avatar large peach">${esc(initials(c.name))}</span><h3 style="margin:12px 0 4px">${esc(c.name)}</h3><p class="small">${c.kind==='person'?'Khách hàng cá nhân':esc(c.org_type||'Tổ chức')}</p>${tag(c.do_not_contact?'Không liên hệ':c.needs_followup?'Cần chăm sóc':'Đã xử lý')}</div><div class="mini-label">THÔNG TIN KHÁCH HÀNG</div>${[['Phụ trách',selected.assignee_name||'Chưa phân công'],['Điện thoại',c.phone||'—'],['Email',c.email||'—'],['Dịch vụ',c.interest||'Chưa ghi nhận']].map(([label,value])=>`<div class="balance"><span>${label}</span><span>${esc(value)}</span></div>`).join('')}${me.role==='leader'&&!v.assignee_id?'<div class="mini-section" id="suggest"><div class="mini-label">SALES ĐƯỢC GỢI Ý</div></div>':''}<div class="mini-section"><div class="mini-label">CƠ HỘI BÁN HÀNG</div>${related.opportunities.slice(0,3).map(o=>`<a href="#/opportunity/${o.id}"><strong>${esc(o.title)}</strong><br><small>${vnd(o.est_value)} · ${esc(o.stage)}</small></a>`).join('')||'<p class="small">Chưa có cơ hội.</p>'}<button id="new-opp">+ Tạo cơ hội</button><button id="plan">${icon('calendar')} Lên lịch tiếp xúc</button><a href="#/customer/${c.id}">Mở hồ sơ khách hàng →</a></div></aside>`:`<section class="chat-pane" style="padding:35px">${empty('Chọn một cuộc trò chuyện','Tạo hội thoại thử từ hồ sơ khách hàng nếu danh sách đang trống.')}<a href="#/customers" style="margin-top:20px">Mở danh bạ khách hàng →</a></section><aside class="customer-aside"><p class="small">Bạn chỉ thấy hội thoại của khách trong phạm vi được giao.</p></aside>`}</div></div>`);
 const fill=()=>{el.querySelector('.inbox-list').innerHTML=list.filter(matches).map(x=>`<a class="conversation-preview ${selected?.id===x.id?'active':''}" href="#/conversation/${x.id}"><div class="identity">${avatar(x.customer_name,channelId(x.channel)==='oa'?'peach':'purple')}<strong>${esc(x.customer_name)}</strong></div><p>${esc(x.last_body||'Chưa có tin nhắn')}</p><div class="preview-foot"><span class="channel-chip">${channelName(x.channel)}</span><span>${x.status==='CLOSED'?'Đã đóng':!x.assignee_id?'Chờ phân công':x.bot_active?'Bot đang hỗ trợ':esc(x.assignee_name)}</span></div></a>`).join('')||empty('Không có hội thoại phù hợp');};fill();
 el.querySelector('#conversation-search').oninput=e=>{inboxFilters.term=e.target.value;fill();};const refilter=()=>{if(location.hash==='#/inbox')render();else go('#/inbox');};el.querySelector('#conversation-status').onchange=e=>{inboxFilters.status=e.target.value;refilter();};action(el,'[data-channel]',b=>{inboxFilters.channel=b.dataset.channel;refilter();});
 if(d){action(el,'#bot',async()=>{await api(`/conversations/${v.id}/bot`,{body:{on:!v.bot_active}});render();});action(el,'#close',async()=>{await api(`/conversations/${v.id}/status`,{body:{status:v.status==='CLOSED'?'OPEN':'CLOSED'}});render();});action(el,'#test-message',()=>form('Tin nhắn khách thử nghiệm',[['body','Nội dung tin nhắn *','textarea',null,'Thời hạn đào tạo tính từ khi nào?'],['outside_hours','Giả lập ngoài giờ làm việc','check']],async body=>{await api(`/conversations/${v.id}/incoming`,{body:{...body,client_key:crypto.randomUUID()}});render();}));
 action(el,'[data-composer]',b=>{composer=b.dataset.composer;el.querySelectorAll('[data-composer]').forEach(x=>x.classList.toggle('selected',x===b));el.querySelector('#reply').placeholder=composer==='note'?'Ghi chú nội bộ cho hồ sơ khách…':'Nhập phản hồi cho khách…';el.querySelector('#reply').disabled=composer==='reply'&&(!v.assignee_id||v.status==='CLOSED');el.querySelector('#send').disabled=el.querySelector('#reply').disabled;el.querySelector('#send').textContent=composer==='note'?'Lưu ghi chú':'Gửi thử';el.querySelector('#composer-hint').textContent=composer==='note'?'Lưu vào hồ sơ, không gửi cho khách.':'Chỉ lưu trong CRM, chưa gửi thật.';});
 action(el,'#send',async()=>{const text=el.querySelector('#reply').value;if(composer==='note'){await api(`/customers/${c.id}/notes`,{body:{body:text}});el.querySelector('#reply').value='';toast('Đã lưu ghi chú nội bộ vào hồ sơ khách.');}else{const r=await api(`/conversations/${v.id}/messages`,{body:{body:text,client_key:crypto.randomUUID()}});toast(r.note);render();}});
 action(el,'#plan',()=>planTask(c));action(el,'#new-opp',()=>newOpportunity(c));
 if(el.querySelector('#suggest')){const s=await api(`/conversations/${v.id}/suggest`),box=el.querySelector('#suggest');box.insertAdjacentHTML('beforeend','<p class="small">Ưu tiên chuyên môn, sau đó số khách cần xử lý.</p>');for(const u of s.list){const b=$(`<button>${esc(u.name)}<small style="display:block">${u.expert?'Đúng chuyên môn':'Khác chuyên môn'} · ${u.load} khách</small></button>`);b.onclick=async()=>{b.disabled=true;try{await api(`/conversations/${v.id}/assign`,{body:{user_id:u.id}});render();}catch(e){toast(e.message);b.disabled=false;}};box.append(b);}}
 setTimeout(()=>{const thread=el.querySelector('.thread');if(thread)thread.scrollTop=thread.scrollHeight;},0);
 }
 return el;
}
views.inbox=async()=>inboxWorkspace();views.conversation=async id=>inboxWorkspace(id);

views.quotes=async()=>{
 const [list,pending]=await Promise.all([api('/quotes'),api('/quotes/pending')]);let filter='all';const el=$(`<div>${pageHeading('Báo giá & phê duyệt','Tạo theo mẫu, duyệt đúng cấp và giữ lịch sử từng phiên bản.',writable()?`<button class="major" id="new">${icon('plus')} Lập báo giá</button>`:'')}<div class="workflow-line"><span>01 · Bản nháp</span>→<span>02 · Trình duyệt</span>→<span>03 · Đã duyệt</span>→<span>04 · Gửi thử</span></div>${pending.length?`<section class="card ready-card"><h3>Chờ bạn duyệt · ${pending.length}</h3><div class="actions">${pending.map(q=>`<a href="#/quote/${q.id}" class="tag ok">${esc(q.code)} · ${esc(q.customer_name)}</a>`).join('')}</div></section>`:''}<section class="card table-card"><div class="filterbar"><div class="segments" style="flex:1;margin:0">${[['all','Tất cả'],['DRAFT','Nháp'],['PENDING','Chờ duyệt'],['APPROVED','Đã duyệt'],['SENT','Đã gửi thử']].map(([value,label])=>`<button data-status="${value}" class="${value==='all'?'selected':''}">${label}<b>${value==='all'?list.length:list.filter(q=>q.status===value).length}</b></button>`).join('')}</div><input type="search" id="search" aria-label="Tìm báo giá" placeholder="Mã báo giá, khách hàng…"></div><table><thead><tr><th>Báo giá</th><th>Khách hàng</th><th>Loại dịch vụ</th><th>Ngày tạo</th><th>Trạng thái</th></tr></thead><tbody></tbody></table><p class="list-meta">Báo giá vượt ngưỡng cần giám đốc duyệt. Gửi thử chưa chuyển nội dung tới Zalo thật.</p></section></div>`);const fill=()=>{const search=el.querySelector('#search').value.toLocaleLowerCase('vi');el.querySelector('tbody').innerHTML=list.filter(q=>(filter==='all'||q.status===filter)&&(q.code+' '+q.customer_name).toLocaleLowerCase('vi').includes(search)).map(q=>`<tr><td><a href="#/quote/${q.id}"><strong>${esc(q.code)}</strong></a><small style="display:block">Phiên bản ${q.version}</small></td><td>${esc(q.customer_name)}</td><td>${esc(q.family_name||(q.template==='training'?'Đào tạo AI':'Smart iVier'))}</td><td>${new Date(q.created_at).toLocaleDateString('vi-VN')}</td><td>${tag(q.status)}</td></tr>`).join('')||'<tr><td colspan="5">Chưa có báo giá phù hợp.</td></tr>';};fill();action(el,'[data-status]',b=>{filter=b.dataset.status;el.querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('selected',x===b));fill();});el.querySelector('#search').oninput=fill;action(el,'#new',()=>newQuote());return el;
};
const existingQuoteView=views.quote;
views.quote=async id=>{const el=await existingQuoteView(id);el.prepend($(`<div class="eyebrow">BÁO GIÁ / KIỂM TRA & PHÊ DUYỆT</div>`));const d=await api('/quotes/'+id);const controls=$(`<div class="quoted-state">${writable()?`<a href="#/customer/${d.customer.id}">Hồ sơ ${esc(d.customer.name)}</a>`:`Khách hàng: ${esc(d.customer.name)}`}${writable()&&d.quote.opp_id?` · <a href="#/opportunity/${d.quote.opp_id}">Cơ hội liên quan</a>`:''}<span style="float:right">${statusText[d.quote.status]}</span></div>`);el.querySelector('.hero').after(controls);return el;};
const existingKnowledgeView=views.knowledge;
views.knowledge=async()=>{const el=await existingKnowledgeView();el.prepend($(`<div class="eyebrow">NỘI DUNG & BOT FAQ</div>`));const flow=$(`<div class="workflow-line"><span>Trưởng nhóm soạn</span>→<span>Giám đốc duyệt</span>→<span>Bot trả lời theo nguồn</span>→<span>Nhân viên tiếp nhận</span></div>`);el.querySelector('.hero').after(flow);return el;};
views.channels=async()=>{const list=await api('/conversations');const el=$(`<div>${pageHeading('Kênh kết nối','Trạng thái thực tế của các điểm chạm với khách hàng.')}<div class="notice">Zalo OA và Zalo cá nhân hiện ở chế độ mô phỏng. Chưa truy cập hoặc gửi tin tới tài khoản Zalo thật.</div><div class="channel-grid">${[['oa','Zalo OA','Tài khoản chính thức iViTech'],['personal','Zalo cá nhân công ty','Phạm vi dự kiến: 1 tài khoản công ty cấp']].map(([id,title,description])=>`<section class="card"><div class="section-heading"><span class="avatar">Z</span>${tag('Mô phỏng')}</div><h3>${title}</h3><p class="small">${description}</p><div class="balance"><span>Hội thoại trong phạm vi</span><strong>${list.filter(c=>channelId(c.channel)===id).length}</strong></div><div class="balance"><span>Nhận/gửi thật</span><span>Chưa kết nối</span></div><div class="balance"><span>Phương thức thử</span><span>Tin nhắn mẫu trong CRM</span></div>${writable()?`<button data-open-channel="${id}" style="margin-top:20px">Mở hộp thư thử →</button>`:''}</section>`).join('')}</div><section class="card" style="margin-top:22px"><h3>Bot FAQ và AI</h3><p>Bot tra nội dung đã được giám đốc duyệt. Sau khi nhân viên tiếp nhận, bot chỉ hoạt động lại khi bấm Chuyển lại cho bot.</p><p class="small">AI tạo sinh, Copilot và gửi tin qua nhà cung cấp chưa được kết nối. Không dùng câu trả lời mô phỏng để nghiệm thu AI thật.</p><a href="#/knowledge">Mở thư viện nội dung →</a></section></div>`);action(el,'[data-open-channel]',b=>{inboxFilters.channel=b.dataset.openChannel;inboxFilters.status='all';inboxFilters.term='';go('#/inbox');});return el;};
const previousGuide=views.guide;
views.guide=async()=>{const el=await previousGuide();el.prepend($(`<div class="role-summary"><strong>Đổi vai trò để kiểm thử:</strong> bấm Đổi tài khoản trên thanh trên cùng → chọn vai trò ở màn hình đăng nhập → Đăng nhập. Bạn có thể gõ tên tài khoản và dùng phím Enter bình thường.<br><strong>Hành trình đề xuất:</strong> Danh bạ → hồ sơ khách → lên kế hoạch / hội thoại → cơ hội → lập báo giá → người có quyền duyệt → gửi thử.</div>`));return el;};
render();


